import React, { useState } from "react";
import { Link } from "react-router-dom";
import { Dropdown, DropdownToggle, DropdownMenu, DropdownItem } from "reactstrap";

const QueryStringElipses = ({ dropDowns, linkItem, deleteFunc }) => {
	const [ dropdownOpen, setDropdownOpen ] = useState(false);

	const toggle = () => setDropdownOpen((prevState) => !prevState);

	return (
		<Dropdown isOpen={dropdownOpen} toggle={toggle}>
			<DropdownToggle className='toggleBtn'>
				<i className='fa fa-ellipsis-v' aria-hidden='true' />
			</DropdownToggle>
			<DropdownMenu>
				{dropDowns.map((dropDownItem, index) => {
					return (
						<span key={index} onClick={dropDownItem.name === "Delete" ? deleteFunc : null}>
							<Link
								// recieves item to delete in action creator. Only for the delete menu
								className={"VisaSettlementLinks"}
								to={
									// A complex general purpose dynamic url contruct
									!dropDownItem.postingDetails ? (dropDownItem.name !== "Delete" ? ( // check if link clicked is not delete and renders link url
										`/${dropDownItem.linkStart}/${dropDownItem.linkEnd}?settlementDate=${linkItem.settlementDate}&region-code=${linkItem.regionCode}${dropDownItem.affiliateCode 
											? `&affiliateCode=${dropDownItem.affiliateCode}`
											: ""}&page=1`// check if the set link has affiliateCode and displays it as query param if present
									) : (
										"#"
                                        )) : `/${dropDownItem.linkStart}/${linkItem.id}/${dropDownItem.linkEnd}`
								}
							>
								<DropdownItem>{dropDownItem.name}</DropdownItem>
							</Link>
						</span>
					);
				})}
			</DropdownMenu>
		</Dropdown>
	);
};

export default QueryStringElipses;
