/* eslint-disable import/first */
// Styles
import "../Batches/datepicker.css";
import "../Transactions/Transactions.css";
import "../Transactions/Transactions.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";
import "react-table/react-table.css";
import "./VisaSettlement.css";

// React
// import classnames from "classnames";
import moment from "moment";
import React, { Component } from "react";
import { Link } from "react-router-dom";
// import { SingleDatePicker } from "react-dates";
import { FormattedMessage } from "react-intl";
import Pagination2 from "react-js-pagination";
import Moment from "react-moment";

// Redux
import { connect } from "react-redux";
import { fetchAllInterAffiliatePostOfficeSummary } from "../../actions/filesets";

// components
import {
	// Button,
	Col,
	Card,
	CardHeader,
	CardBody,
	Row,
	Table,
} from "reactstrap";
// import SettlementTable from '../../components/SettlementTable'
import QueryStringElipses from "../../components/QueryStringElipsis";

require("jspdf-autotable");

class InterAffiliateSettlement extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activePage     : 1,
			activeTab      : "1",
			activeTab2     : "3",
			activePageT112 : 1,
			activePageT464 : 1,
			activePageT140 : 1,
			activePageT461 : 1,
			date           : new Date(),
			startDate      : moment(),
			endDate        : moment(),
			focusedInput   : null,
		};
		this.handleChange = this.handleChange.bind(this);
		this.submitDate = this.submitDate.bind(this);
	}

	componentDidMount () {
		let date1 = moment(this.state.startDate).format();

		if (date1.includes("T")) {
			let extract = date1.split("T");
			date1 = extract[0];
		}
		this.props.fetchAllInterAffiliatePostOfficeSummary();
	}

	handlePageChange = (pageNumber) => {
		let pageNumberParam = pageNumber - 1;
		this.props.fetchBatchesTransactions(this.props.match.params.id, pageNumberParam);
		this.setState({ activePage: pageNumber });
	};

	showPostingFile = (date) => {
		this.props.history.push(`/interAffiliate/settlement/${date}/summary`);
	};

	handleChange (date) {
		this.setState({
			startDate : date,
		});
	}

	submitDate () {
		let date1 = moment(this.state.startDate).format();

		if (date1.includes("T")) {
			let extract = date1.split("T");
			date1 = extract[0];
			this.setState({ paramsDate: date1 });
		}
		this.props.fetchInterAffiliatePostingOverview(date1);
	}

	onFocusChange = (focusedInput) => {
		this.setState({ focusedInput });
	};

	toggle (tab) {
		if (this.state.activeTab !== tab) {
			this.setState({
				activeTab : tab,
			});
		}
	}
	toggleTab2 (tab) {
		if (this.state.activeTab2 !== tab) {
			this.setState({
				activeTab2 : tab,
			});
		}
	}

	render () {
		return (
			<div className='animated fadeIn'>
				<Row>
					<Col xs='12' md='12' className='mb-4'>
						<Card>
							<CardHeader>
								{this.props.fileSets.interAffiliatePostOffice ? (
									<FormattedMessage
										id='Inter Affiliate Settlement'
										defaultMessage='Inter Affiliate Settlement'
									/>
								) : (
									""
								)}
							</CardHeader>
							<CardBody>
								{/* Handle Error */}
								{this.props.interAffiliatePostOfficeError &&
								!this.props.interAffiliatePostOffice && (
									<article className='text-danger d-flex justify-content-center align-items-center py-4'>
										<FormattedMessage
											id={this.props.interAffiliatePostOfficeError.data.message}
											defaultMessage={this.props.interAffiliatePostOfficeError.data.message}
										/>
									</article>
								)}

								<Table
									hover
									bordered
									striped
									size='sm'
									className='table-outline mb-0 d-sm-table'
									id='divToPDF'
								>
									{/* Handle display content */}
									{/* Handle header display */}
									{!this.props.interAffiliatePostOfficeError &&
									this.props.interAffiliatePostOffice &&
									this.props.interAffiliatePostOffice.data &&
									this.props.interAffiliatePostOffice.data.content.length > 0 && (
										<thead className='thead-light'>
											<tr>
												<th>
													<FormattedMessage id='Date' defaultMessage='Date' />{" "}
												</th>
												<th>
													<FormattedMessage id='File Name' defaultMessage='File Name' />
												</th>
												<th>
													<FormattedMessage id='Region' defaultMessage='Region' />
												</th>
												<th>
													<FormattedMessage id='Action' defaultMessage='Action' />
												</th>
											</tr>
										</thead>
									)}
									{!this.props.interAffiliatePostOfficeError &&
										this.props.interAffiliatePostOffice &&
										this.props.interAffiliatePostOffice.data &&
										this.props.interAffiliatePostOffice.data.content.length > 0 &&
										this.props.interAffiliatePostOffice.data.content.map((item, index) => {
											return (
												<tbody>
													<tr key={index}>
														<td>
															<Moment format='ll'>{item["settlementDate"]}</Moment>
														</td>
														<td>
															<Link to={"#"} style={{ textDecoration: "none" }}>
																{item["filename"] ? item["filename"] : "N/A"}
															</Link>
														</td>
														<td>
															<Link to={"#"} style={{ textDecoration: "none" }}>
																{item["filename"] ? item["regionCode"] : "N/A"}
															</Link>
														</td>
														<td>
															<span className='d-flex justify-content-between align-items-center w-25'>
																{" "}
																<QueryStringElipses
																	linkItem={item}
																	deleteFunc={null}
																	dropDowns={[
																		{
																			name          : "Issuer",
																			linkStart     :
																				"interaffiliate/settlement/reports",
																			linkEnd       : "issuer-item",
																			affiliateCode : "USD",
																		},
																		{
																			name          : "Acquirer",
																			linkStart     :
																				"interaffiliate/settlement/reports",
																			linkEnd       : "acquirer-item",
																			affiliateCode : "USD",
																		},
																		{
																			name      : "Posting Report",
																			linkStart :
																				"interaffiliate/settlement/reports",
																			linkEnd   : "affiliate-posting-report",
																		},
																		{
																			name          : "Posting Summary",
																			linkStart     :
																				"interaffiliate/settlement/reports",
																			linkEnd       : "posting-summary",
																			affiliateCode : "CV",
																		},
																		{
																			name           : "Posting Details",
																			linkStart      :
																				"interaffiliate/settlement/reports",
																			linkEnd        : "posting-details",
																			postingDetails : true,
																		},
																	]}
																/>
															</span>
														</td>
													</tr>
												</tbody>
											);
										})}
								</Table>

								{this.props.fileSets.interAffiliateiIssuers ? (
									<nav>
										<Pagination2
											activePage={this.state.activePageT140}
											itemsCountPerPage={10}
											totalItemsCount={
												this.props.fileSets.interAffiliateiIssuers ? (
													this.props.fileSets.interAffiliateiIssuers.data.totalElements
												) : null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChangeT140}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		fileSets                            : state.fileSets,
		interAffiliatePostOffice            : state.fileSets.interAffiliatePostOffice,
		interAffiliatePostOfficeError       : state.fileSets.interAffiliatePostOfficeError,
		interAffiliate_source_summary       : state.fileSets.interAffiliate_source_summary,
		interAffiliate_source_summary_error : state.fileSets.interAffiliate_source_summary_error,
		utils                               : state.utils,
	};
};

export default connect(mapStateToProps, {
	fetchAllInterAffiliatePostOfficeSummary,
})(InterAffiliateSettlement);
